const CONFIG=window.__URBANSIGHT_CONFIG__||{};
const API=(CONFIG.apiUrl||window.location.origin).replace(/\/$/,'');
const WS=CONFIG.wsUrl||(API.replace(/^http/,'ws')+'/ws');
const state={page:'home',loading:true,error:'',live:false,toast:'',speed:2,selected:null,searchOpen:false,searchResults:[],lastEvent:null,maintenance:null,counts:{issues:0,incidents:0,buses:0,alerts:0,maintenance:0},issues:[],buses:[],incidents:[],traffic:{},analytics:{},reports:null,maintenanceRows:[],mapLayers:'all',searchResults:[]};
let liveMap=null; const liveBusMarkers=new Map();
const icons={overview:'▦',map:'⌖',issues:'◈',traffic:'≋',incidents:'!',buses:'▰',maintenance:'✓',analytics:'◒',reports:'▤'};
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const fmt=n=>Number(n??0).toLocaleString();
function toast(msg){state.toast=msg;render();setTimeout(()=>{state.toast='';render()},2600)}
function badge(v){return `<span class="badge ${esc(String(v||'').toLowerCase().replaceAll(' ','-'))}">${esc(v||'—')}</span>`}
async function api(path,opts={}){const r=await fetch(API+path,{...opts,headers:{'content-type':'application/json',...(opts.headers||{})}});const data=await r.json().catch(()=>({}));if(!r.ok)throw new Error(data.error?.message||data.error||`Request failed (${r.status})`);return data}
async function hydrate(){state.loading=true;state.error='';render();try{const [d,i,b,c,t,a,r,m]=await Promise.all(['/api/dashboard','/api/road-issues','/api/buses','/api/incidents','/api/traffic','/api/analytics','/api/reports/daily','/api/maintenance'].map(x=>api(x)));state.counts={issues:d.activeIssues,incidents:d.criticalIncidents,buses:d.busesOnline,alerts:d.trafficAlerts,maintenance:d.pendingMaintenance};state.live=d.simulation?.status==='RUNNING';state.speed=d.simulation?.speed||2;state.simulation=d.simulation;state.lastEvent=d.simulation?.latestDetection||state.lastEvent;state.issues=i;state.buses=b;state.incidents=c;state.traffic=t;state.analytics=a;state.reports=r;state.maintenanceRows=m;state.maintenance=state.maintenance||m[0]||null}catch(e){state.error=e.message}finally{state.loading=false;render()}}
function home(){return `<div class="site"><nav class="nav"><a class="brand" href="#/"><span class="brand-mark">U</span><span>Urban<span class="brand-accent">Sight</span></span></a><div class="nav-links"><a href="#how">How it works</a><a href="#capabilities">Capabilities</a><a href="#impact">Impact</a><a href="#/dashboard">Dashboard</a></div><a class="button dark" href="#/dashboard">Get started <span>↗</span></a></nav><main><section class="hero"><div class="hero-copy"><div class="eyebrow"><span class="pulse"></span> FLEET-WIDE URBAN VISIBILITY</div><h1>Every bus.<br><em>A smarter view</em><br>of the city.</h1><p class="lead">UrbanSight transforms public transport into a mobile intelligence network—helping city teams detect road defects, traffic conditions and critical incidents as they happen.</p><div class="hero-actions"><a class="button dark" href="#/dashboard">Enter command centre <span>→</span></a><a class="text-link" href="#how">See how it works <span>↓</span></a></div><div class="hero-proof"><span class="proof-icon">✦</span><span><b>Database-backed operations</b><br><small>Across Mumbai metropolitan routes</small></span></div></div><div class="hero-visual"><div class="city-label">MUMBAI · LIVE NETWORK <span>●</span></div><div class="road r1"></div><div class="road r2"></div><div class="road r3"></div><div class="route-line"></div><div class="bus-shape"><div class="bus-window"></div><div class="bus-window second"></div><span>URBANSIGHT</span></div><div class="scan scan-a"><b>BUS-042</b><small>Mobile sensor active</small></div><div class="scan scan-b"><b>POSTGIS</b><small>Spatial issue fusion</small></div><div class="map-coord">19.0760° N<br>72.8777° E</div></div></section><section class="quiet-strip"><div><b>01</b><span>Detect problems earlier</span></div><div><b>02</b><span>Prioritize with evidence</span></div><div><b>03</b><span>Verify the repair</span></div></section><section class="section problem" id="how"><div class="section-kicker">THE GAP IN CITY VISIBILITY</div><h2>Static cameras see a point.<br><em>A moving fleet sees the network.</em></h2><div class="problem-grid"><p>UrbanSight combines edge observations, location context, repeat detection and maintenance evidence into one operational picture.</p><div class="problem-list"><div><span>01</span>Delayed road maintenance</div><div><span>02</span>Incomplete situational awareness</div><div><span>03</span>Slower incident response</div></div></div></section><section class="section approach"><div class="section-kicker">THE URBANSIGHT APPROACH</div><h2>One fleet. <em>Many signals.</em><br>One operational picture.</h2><div class="flow"><div><b>01</b><strong>Bus camera</strong><small>Observe the road</small></div><i>→</i><div><b>02</b><strong>Edge AI</strong><small>Understand events</small></div><i>→</i><div><b>03</b><strong>GPS context</strong><small>Locate precisely</small></div><i>→</i><div><b>04</b><strong>Action</strong><small>Help teams respond</small></div></div></section><section class="section capabilities" id="capabilities"><div class="section-kicker">WHAT THE PLATFORM DETECTS</div><div class="cap-head"><h2>Signals that matter<br><em>on the street.</em></h2><p>Every observation carries a confidence score, location, timestamp and evidence trail.</p></div><div class="cap-grid">${['Potholes & road damage','Traffic bottlenecks','Waterlogging','Missing infrastructure','Vulnerable pedestrians','Incidents & ANPR'].map((x,i)=>`<div class="cap-card"><span>0${i+1}</span><h3>${x}</h3><p>Operational signal with backend evidence and repeat-observation context.</p><a href="#/dashboard">Explore signal ↗</a></div>`).join('')}</div></section><section class="section impact" id="impact"><div class="impact-panel"><div class="section-kicker">FROM DETECTION TO ACTION</div><h2>A city that can<br><em>close the loop.</em></h2><p>Detection, geolocation, repeat observation, maintenance and repair verification in one workflow.</p><a class="button light" href="#/dashboard">Explore the platform <span>→</span></a></div><div class="impact-steps">${['Detection','Geolocation','Repeated observation','Maintenance ticket','Repair verification'].map((x,i)=>`<div><span>0${i+1}</span><b>${x}</b><i>↗</i></div>`).join('')}</div></section></main><footer><span class="brand"><span class="brand-mark">U</span> UrbanSight</span><span>Mobile urban intelligence for more responsive cities.</span><span>SIH26124 · 2026</span></footer></div>`}
function kpi(label,value,delta,icon,accent=''){return `<div class="kpi ${accent}"><div class="kpi-top"><span>${label}</span><b>${icon}</b></div><strong>${fmt(value)}</strong><small><em>${esc(delta)}</em> backend</small></div>`}
function map(){return `<div class="map-toolbar"><button class="${state.mapLayers==='all'?'selected':''}" onclick="setMapLayer('all')">All</button><button class="${state.mapLayers==='issues'?'selected':''}" onclick="setMapLayer('issues')">Issues</button><button class="${state.mapLayers==='fleet'?'selected':''}" onclick="setMapLayer('fleet')">Fleet</button><button class="${state.mapLayers==='traffic'?'selected':''}" onclick="setMapLayer('traffic')">Traffic</button><button class="${state.mapLayers==='incidents'?'selected':''}" onclick="setMapLayer('incidents')">Incidents</button></div><div id="gis-map" class="map" aria-label="Interactive backend map"></div>`}
function issueTable(rows){return `<div class="table-wrap"><table><thead><tr><th>Issue</th><th>Location</th><th>Severity</th><th>Confidence</th><th>Observations</th><th>Status</th></tr></thead><tbody>${rows.length?rows.map(x=>`<tr data-issue="${esc(x.id)}" onclick="viewIssue('${esc(x.id)}')"><td><b>${esc(x.id)}</b><small>${esc(x.type)}</small></td><td>${esc(x.location||`${x.lat}, ${x.lon}`)}</td><td>${badge(x.severity)}</td><td><b>${esc(x.confidence)}%</b></td><td>${esc(x.observations)}</td><td>${badge(x.status)}</td></tr>`).join(''):'<tr><td colspan="6">No issues found.</td></tr>'}</tbody></table></div>`}
function searchPanel(){if(!state.searchOpen)return '';return `<div class="search-overlay"><div class="panel search-panel"><div class="panel-head"><h3>Search operations</h3><button class="icon-button" onclick="closeSearch()">×</button></div><input autofocus placeholder="RD-1042, BUS-042, INC-0281 or R17" oninput="searchOperations(this.value)"><div class="search-results">${state.searchResults.map(x=>`<button onclick="openSearchResult('${esc(x.kind)}','${esc(x.id)}')"><b>${esc(x.id)}</b><span>${esc(x.kind)} · ${esc(x.type||x.route||x.status||'')}</span></button>`).join('')||'<small>Type an issue, bus, incident or route.</small>'}</div></div></div>`}
function shell(content){const staticPage=state.page==='settings'||state.page==='profile';return `<div class="app-shell"><aside class="sidebar"><a class="brand" href="#/"><span class="brand-mark">U</span><span>Urban<span class="brand-accent">Sight</span></span></a><div class="side-label">OPERATIONS</div><div class="side-nav">${Object.entries(icons).map(([key,ic])=>`<a class="${state.page===key?'active':''}" href="#/dashboard/${key}"><span class="side-icon">${ic}</span>${key[0].toUpperCase()+key.slice(1)}</a>`).join('')}</div><div class="side-label bottom">SYSTEM</div><div class="side-nav"><a class="${state.page==='settings'?'active':''}" href="#/dashboard/settings"><span class="side-icon">⚙</span>Settings</a><a class="${state.page==='profile'?'active':''}" href="#/dashboard/profile"><span class="side-icon">◉</span>Profile</a></div><div class="user-card"><div class="avatar">AS</div><div><b>Ananya Shah</b><small>Transport Authority${demoModeLabel()}</small></div><span>⋮</span></div></aside><section class="workspace"><header class="topbar"><div><span class="crumb">URBANSIGHT /</span><b>${esc(state.page.toUpperCase())}</b>${state.live?'<span class="demo-badge">● SIMULATION RUNNING</span>':''}</div><div class="top-actions"><button class="search" onclick="focusSearch()">⌕ <span>Search operations</span><kbd>⌘ K</kbd></button><button class="icon-button" onclick="showNotifications()">♢<span class="notify-dot"></span></button><div class="city-select">Mumbai Metropolitan Region⌄</div></div></header><main class="dash-content">${state.loading&&!staticPage?'<div class="panel empty-state">Loading operational data…</div>':state.error&&!staticPage?`<div class="panel error-state"><b>Backend unavailable</b><p>${esc(state.error)}</p><button class="button dark" onclick="hydrate()">Retry</button></div>`:content}</main></section>${searchPanel()}${state.toast?`<div class="toast">✓ &nbsp;${esc(state.toast)}</div>`:''}</div>`}
function demoModeLabel(){return (CONFIG.demoMode||location.hostname==='localhost')?' · DEMO MODE':''}
function demoPanel(){const s=state.simulation||{};return `<div class="panel demo-panel"><div class="demo-panel-head"><div><span class="section-kicker">LIVE DEMO SIMULATION</span><h3>Bus-to-city intelligence pipeline</h3></div><span class="demo-status ${state.live?'running':'stopped'}">● ${state.live?'RUNNING':'READY'}</span></div><div class="demo-stats"><div><small>Current bus</small><b>${esc(s.currentBus||state.buses[0]?.id||'BUS-042')}</b></div><div><small>Route</small><b>${esc(s.currentRoute||state.buses[0]?.route||'R17')}</b></div><div><small>Events</small><b>${fmt(s.eventsGenerated||0)}</b></div><div><small>Latest</small><b>${esc(s.latestDetection||state.lastEvent||'Ready to start')}</b></div></div><div class="demo-actions"><button class="button dark" onclick="simulationAction('${state.live?'pause':'start'}')">${state.live?'Ⅱ Pause':'▶ Start'}</button><button class="button outline" onclick="simulationAction('resume')">Resume</button><button class="button outline" onclick="simulationAction('stop')">Stop</button><button class="button outline" onclick="simulationAction('reset')">Reset</button></div><small class="demo-note">SIMULATED BUS / EDGE AI · Real backend, PostGIS persistence and WebSocket updates</small></div>`}
function selectedIssuePanel(){const x=state.selected;if(!x?.id)return '';return `<div class="panel selected-issue"><div class="panel-head"><div><span class="section-kicker">ROAD ISSUE DETAIL</span><h3>${esc(x.id)} · ${esc(x.type)}</h3></div>${badge(x.status)}</div><div class="detail-grid"><div><small>Severity</small><b>${esc(x.severity)}</b></div><div><small>Confidence</small><b>${esc(x.confidence)}%</b></div><div><small>Observations</small><b>${esc(x.observation_count||x.observations?.length||x.observations||0)}</b></div><div><small>Buses</small><b>${esc(x.supportingBuses||x.buses_observed||0)}</b></div></div><p class="reason">${esc(x.reason||'Multiple buses independently observed the same road defect.')}</p><div class="head-actions"><button class="button dark" onclick="createWorkOrder('${esc(x.id)}')">Create work order</button><button class="button outline" onclick="viewEvidence('${esc(x.id)}')">View evidence</button></div></div>`}
function overview(){return `<div class="page-head"><div><div class="section-kicker">DATABASE-BACKED OPERATIONS</div><h1>Good evening, Ananya.</h1><p>Operational picture across the fleet and road network.</p></div><div class="head-actions"><button class="button outline" onclick="generateReport()">▤ Generate report</button><button class="button dark" onclick="simulationAction('${state.live?'pause':'start'}')">${state.live?'Ⅱ Pause simulation':'▶ Start live simulation'}</button><button class="button outline" onclick="simulationAction('reset')">↺ Reset</button><span class="speed-controls">${[1,2,5,10].map(x=>`<button class="button small ${state.speed===x?'dark':'outline'}" onclick="setSpeed(${x})">${x}x</button>`).join('')}</span></div></div>${demoPanel()}<div class="kpis">${kpi('Active road issues',state.counts.issues,'live','◈','critical')}${kpi('Critical incidents',state.counts.incidents,'live','!','critical')}${kpi('Buses online',state.counts.buses,'live','▰','healthy')}${kpi('Traffic alerts',state.counts.alerts,'24h','≋','warning')}${kpi('Pending maintenance',state.counts.maintenance,'open','✓','')}</div><div class="dashboard-grid"><div class="panel map-panel"><div class="panel-head"><div><b>City intelligence map</b><small>Backend issues · traffic · fleet</small></div></div>${map()}</div><div class="panel activity"><div class="panel-head"><div><b>Live activity</b><small><span class="live-dot"></span> WebSocket feed</small></div><a href="#/dashboard/incidents">View all</a></div><div class="activity-list">${state.incidents.slice(0,4).map(x=>`<div><span class="activity-icon red">!</span><div><b>${esc(x.id)} · ${esc(x.type)}</b><small>${esc(x.vehicle)} · ${esc(x.status)}</small></div><time>live</time></div>`).join('')||'<div class="empty-state">No recent activity.</div>'}</div></div></div>${selectedIssuePanel()}<div class="bottom-grid"><div class="panel"><div class="panel-head"><div><b>Road issue priority queue</b><small>Sorted from PostgreSQL</small></div><a href="#/dashboard/issues">View all issues →</a></div>${issueTable(state.issues.slice(0,5))}</div><div class="panel mini-chart"><div class="panel-head"><div><b>Traffic trend</b><small>24-hour measurements</small></div><span class="trend">${esc(state.traffic.congestion||0)}%</span></div><div class="chart"><div class="bars">${(state.traffic.trend||[]).map((h,i)=>`<i style="height:${Math.max(5,h)}%" class="${i>8?'hot':''}"></i>`).join('')}</div></div></div></div>`}
function issuesPage(){return `<div class="page-head"><div><div class="section-kicker">URBAN INTELLIGENCE</div><h1>Road issues</h1><p>Every observation fused into a persistent road condition.</p></div><button class="button dark" onclick="createWorkOrder('${esc(state.issues[0]?.id||'RD-1042')}')">+ Create work order</button></div><div class="filterbar"><div class="search-field">⌕ <input placeholder="Search issue ID, location or type" oninput="filterIssues(this.value)"></div><span class="filter-count">${state.issues.length} backend issues</span></div><div class="panel full-panel"><div id="issue-table">${issueTable(state.issues)}</div></div>${selectedIssuePanel()}`}
function trafficPage(){const t=state.traffic||{};return `<div class="page-head"><div><div class="section-kicker">NETWORK FLOW</div><h1>Traffic intelligence</h1><p>Vehicle movement and congestion across monitored corridors.</p></div><button class="button outline" onclick="exportJson('traffic-summary.json',state.traffic)">⇩ Export summary</button></div><div class="traffic-kpis">${kpi('Vehicles observed',t.vehicleCount,'database','▱')}${kpi('Average speed',t.averageSpeed+' km/h','database','↗')}${kpi('Congestion level',t.congestion+'%','database','≋','warning')}</div><div class="two-col"><div class="panel large-chart"><div class="panel-head"><div><b>Traffic density · 24 hours</b><small>Aggregated from PostgreSQL</small></div></div><div class="chart"><div class="bars">${(t.trend||[]).map((h,i)=>`<i style="height:${Math.max(5,h)}%" class="${i>8?'hot':''}"></i>`).join('')}</div></div></div><div class="panel route-rank"><div class="panel-head"><div><b>Most congested routes</b><small>Backend aggregation</small></div></div>${(t.routes||[]).map(x=>`<div class="rank"><b>${esc(x.route)}</b><span>${esc(x.name)}</span><i><em style="width:${x.index}%"></em></i><strong>${x.index}</strong></div>`).join('')}</div></div>`}
function incidentsPage(){return `<div class="page-head"><div><div class="section-kicker">SAFETY OPERATIONS</div><h1>Incidents</h1><p>Serious events requiring human review.</p></div><button class="button outline" onclick="exportJson('incidents.json',state.incidents)">▤ Incident report</button></div><div class="incident-grid">${state.incidents.length?state.incidents.map(x=>`<div class="panel incident-card"><div class="incident-top"><span class="incident-icon">!</span><div><b>${esc(x.id)}</b><small>${esc(x.timestamp)}</small></div>${badge(x.status)}</div><h3>${esc(x.type)}</h3><div class="detail-row"><span>Vehicle</span><b>${esc(x.vehicle)}</b></div><div class="detail-row"><span>Confidence</span><b>${esc(x.confidence)}%</b></div><div class="detail-row"><span>Location</span><b>${esc(x.location)}</b></div><div class="evidence">${x.evidence_url?'Evidence attached':'DEMO SIMULATION evidence'} <span>↗</span></div><button class="button small outline" onclick="viewEvidence('${esc(x.id)}')">View evidence</button></div>`).join(''):'<div class="panel empty-state">No incidents.</div>'}</div>`}
function busesPage(){return `<div class="page-head"><div><div class="section-kicker">FLEET TELEMETRY</div><h1>Bus fleet</h1><p>${state.counts.buses} buses currently online from PostgreSQL.</p></div><button class="button dark" onclick="simulationAction('${state.live?'pause':'start'}')">${state.live?'Ⅱ Pause live feed':'▶ Start live feed'}</button></div><div class="panel full-panel"><div class="table-wrap"><table><thead><tr><th>Bus</th><th>Status</th><th>Route</th><th>Current location</th><th>Last event</th><th>Events today</th></tr></thead><tbody>${state.buses.map(x=>`<tr onclick="viewBus('${esc(x.id)}')"><td><b>${esc(x.id)}</b></td><td>${badge(x.status)}</td><td>${esc(x.route)}</td><td>${esc(x.location)}</td><td>${esc(x.lastEvent||'—')}</td><td>${esc(x.events)}</td></tr>`).join('')}</tbody></table></div></div>`}
function maintenancePage(){const task=state.maintenance||state.maintenanceRows[0];const steps=['DETECTED','VERIFIED','ASSIGNED','IN_PROGRESS','RESOLVED','REPAIR_VERIFIED'];const index=steps.indexOf(task?.status||'DETECTED');return `<div class="page-head"><div><div class="section-kicker">CLOSE THE LOOP</div><h1>Maintenance workflow</h1><p>Every transition persists in PostgreSQL and audit history.</p></div><button class="button dark" onclick="createWorkOrder('${esc(task?.issue_id||state.issues[0]?.id||'RD-1042')}')">+ Create work order</button></div><div class="workflow"><div class="workflow-track">${steps.map((x,i)=>`<div class="workflow-step ${i<=index?'done':''} ${i===index?'current':''}"><span>${i<=index?'✓':i+1}</span><b>${x.replaceAll('_',' ')}</b></div>`).join('')}</div></div><div class="panel work-panel">${task?`<div class="work-title"><div><span class="issue-code">${esc(task.issue_id)}</span><h2>${esc(task.department)}</h2><p>${badge(task.status)} · Work order ${esc(task.id)}</p></div><button class="button dark" ${index>=steps.length-1?'disabled':''} onclick="advanceMaintenance('${esc(task.id)}','${steps[Math.min(index+1,steps.length-1)]}')">${index>=steps.length-1?'Repair verified':'Advance status →'}</button></div><div class="work-grid"><div><h3>Persisted workflow</h3><div class="reason"><span>Current status</span><b>${esc(task.status)}</b></div><div class="reason"><span>Updated</span><b>${esc(task.updated_at||'—')}</b></div></div><div><h3>Evidence trail</h3><p class="muted">Before evidence: demo://evidence/simulated-frame.jpg</p><p class="muted">After evidence: ${task.repair_verified_at?'verified timestamp recorded':'pending repair verification'}</p><button class="button small outline" onclick="viewEvidence('${esc(task.issue_id)}')">View evidence</button></div></div>`:'<div class="empty-state">No work order exists. Create one from a road issue.</div>'}</div>`}
function analyticsPage(){const a=state.analytics||{};return `<div class="page-head"><div><div class="section-kicker">DECISION SUPPORT</div><h1>Analytics</h1><p>Calculated from PostgreSQL operational records.</p></div><button class="button outline" onclick="exportJson('analytics.json',state.analytics)">⇩ Export snapshot</button></div><div class="analytics-grid"><div class="panel insight"><span class="insight-label">MOST AFFECTED CORRIDOR</span><strong>${esc(a.mostAffectedRoute)}</strong><p>${esc(a.mostAffectedCount)} active issues</p><div class="insight-number">${esc(a.mostAffectedCount)}</div></div><div class="panel insight"><span class="insight-label">AVERAGE RESOLUTION TIME</span><strong>${esc(a.averageResolutionDays)} days</strong><p>From persisted repair timestamps</p><div class="insight-number green-text">${esc(a.repairVerificationRate)}%</div></div><div class="panel category-chart"><div class="panel-head"><div><b>Issues by category</b><small>Backend aggregation</small></div></div>${(a.issuesByType||[]).map(x=>`<div class="category"><span>${esc(x.type)}</span><i><em style="width:${Math.min(100,Number(x.count)*20)}%"></em></i><b>${esc(x.count)}</b></div>`).join('')}</div></div>`}
function reportsPage(){return `<div class="page-head"><div><div class="section-kicker">EVIDENCE & ACCOUNTABILITY</div><h1>Reports</h1><p>Actual database-backed daily report${state.reports?.generatedAt?' · refreshed '+new Date(state.reports.generatedAt).toLocaleTimeString():''}.</p></div><button class="button dark" onclick="generateReport()">+ Generate report</button></div><div class="report-grid">${[['Daily Urban Intelligence Report','Complete operational snapshot'],['Road Condition Report','Defects, severity and repair status'],['Traffic Summary','Flow, speed and corridors'],['Maintenance Report','Open work orders and verification']].map((x,i)=>`<div class="panel report-card"><div class="report-icon">${['◫','◈','≋','✓'][i]}</div><h3>${x[0]}</h3><p>${x[1]}</p><small>Database generated</small><button class="text-link" onclick="openReport('${i}')">Open report ↗</button></div>`).join('')}</div>`}
function settingsPage(){return `<div class="page-head"><div><div class="section-kicker">SYSTEM</div><h1>Settings</h1><p>Runtime configuration visible to this frontend.</p></div></div><div class="panel settings"><div class="detail-row"><span>API endpoint</span><b>${esc(API)}</b></div><div class="detail-row"><span>WebSocket endpoint</span><b>${esc(WS)}</b></div><div class="detail-row"><span>Mode</span><b>${esc(demoModeLabel().trim()||'PRODUCTION')}</b></div><div class="detail-row"><span>Issue radius</span><b>Backend configured</b></div><button class="button outline" onclick="hydrate()">Refresh connection</button></div>`}
function profilePage(){return `<div class="page-head"><div><div class="section-kicker">ACCOUNT</div><h1>Profile</h1><p>Current demo operator identity.</p></div></div><div class="panel settings"><div class="user-card large"><div class="avatar">AS</div><div><b>Ananya Shah</b><small>Transport Authority</small></div></div><div class="detail-row"><span>Role</span><b>TRANSPORT_AUTHORITY</b></div><div class="detail-row"><span>Authorization</span><b>${demoModeLabel().trim()?'DEMO MODE':'TOKEN VERIFIED'}</b></div></div>`}
function pageContent(){if(state.page==='overview')return overview();if(state.page==='map')return `<div class="page-head"><div><div class="section-kicker">GEOSPATIAL OPERATIONS</div><h1>Map</h1><p>Backend-fed spatial layers.</p></div></div><div class="panel map-panel">${map()}</div>${selectedIssuePanel()}`;if(state.page==='issues')return issuesPage();if(state.page==='traffic')return trafficPage();if(state.page==='incidents')return incidentsPage();if(state.page==='buses')return busesPage();if(state.page==='maintenance')return maintenancePage();if(state.page==='analytics')return analyticsPage();if(state.page==='reports')return reportsPage();if(state.page==='settings')return settingsPage();if(state.page==='profile')return profilePage();return `<div class="panel error-state"><b>Unknown dashboard route</b><p>This route is not implemented.</p><a class="button dark" href="#/dashboard">Return to overview</a></div>`}
function render(){document.getElementById('app').innerHTML=state.page==='home'?home():shell(pageContent());if(state.page!=='home'&&!state.loading&&!state.error)setTimeout(initMap,0)}
function initMap(){if(!window.L||!document.getElementById('gis-map'))return;const m=L.map('gis-map',{zoomControl:true}).setView([19.076,72.877],12);liveMap=m;L.tileLayer('https://{s}.tile.openstreetmap.org/{z}/{x}/{y}.png',{attribution:'© OpenStreetMap contributors'}).addTo(m);const add=(lat,lon,color,label,kind)=>{if(state.mapLayers!=='all'&&state.mapLayers!==kind)return;return L.circleMarker([lat,lon],{radius:7,color,fillColor:color,fillOpacity:.85}).addTo(m).bindPopup(label)};if(state.mapLayers!=='fleet')state.issues.forEach(x=>add(x.lat,x.lon,x.severity==='CRITICAL'?'#bb5346':x.severity==='HIGH'?'#c8643b':'#b8892d',`<b>${esc(x.id)}</b><br>${esc(x.type)}<br>${esc(x.confidence)}% confidence<br>${esc(x.observations)} observations<br><button onclick="viewIssue('${esc(x.id)}')">Open issue</button>`,'issues'));if(state.mapLayers==='all'||state.mapLayers==='fleet')state.buses.forEach(x=>{const marker=add(x.lat,x.lon,'#3f6f84',`<b>${esc(x.id)}</b><br>${esc(x.route)}<br>${esc(x.status)}`,'fleet'); if(marker)liveBusMarkers.set(x.id,marker)});if(state.mapLayers==='all'||state.mapLayers==='incidents')state.incidents.forEach(x=>add(x.lat,x.lon,'#8b4f64',`<b>${esc(x.id)}</b><br>${esc(x.type)}<br>${esc(x.status)}`,'incidents'))}
function route(){const parts=location.hash.replace(/^#\/?/,'').split('/');state.page=parts[0]==='dashboard'?(parts[1]||'overview'):'home';render();window.scrollTo(0,0)}
async function simulationAction(action){try{const x=await api('/api/simulation/'+action,{method:'POST'});state.live=x.status==='RUNNING';state.speed=x.speed;state.simulation=x;toast(action==='start'?'Demo simulation running':`${action} completed`);await hydrate()}catch(e){toast(e.message)}}
async function setSpeed(speed){state.speed=speed;try{await api('/api/simulation/speed',{method:'POST',body:JSON.stringify({speed})});toast(`Simulation speed ${speed}x`)}catch(e){toast(e.message)}}
async function createWorkOrder(issueId){try{const row=await api('/api/maintenance',{method:'POST',body:JSON.stringify({issueId})});state.maintenance=row;toast(`Work order ${row.id} created`);await hydrate();location.hash='#/dashboard/maintenance'}catch(e){toast(e.message)}}
async function advanceMaintenance(id,status){try{const row=status==='REPAIR_VERIFIED'?await api('/api/maintenance/'+id+'/rescan',{method:'POST'}):await api('/api/maintenance/'+id,{method:'PATCH',body:JSON.stringify({status})});state.maintenance=row;toast(status==='REPAIR_VERIFIED'?'AI rescan complete · road surface clear':`Status persisted as ${status}`);await hydrate()}catch(e){toast(e.message)}}
async function generateReport(){try{state.reports=await api('/api/reports/daily');exportJson('urbansight-daily-report.json',state.reports);toast('Report downloaded from backend data')}catch(e){toast(e.message)}}
function openReport(){generateReport()}
async function viewIssue(id){try{state.selected=await api('/api/road-issues/'+id);render();toast(`${id} loaded from backend`)}catch(e){toast(e.message)}}
async function viewBus(id){try{state.selected=await api('/api/buses/'+id);toast(`${id} loaded from backend`)}catch(e){toast(e.message)}}
async function viewEvidence(id){try{const e=await api('/api/evidence/'+id);toast(`${e.mode}: ${e.message}`)}catch(err){toast(err.message)}}
function exportJson(name,data){const blob=new Blob([JSON.stringify(data,null,2)],{type:'application/json'});const a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download=name;a.click();URL.revokeObjectURL(a.href)}
function filterIssues(q){const rows=state.issues.filter(x=>JSON.stringify(x).toLowerCase().includes(q.toLowerCase()));const el=document.getElementById('issue-table');if(el)el.innerHTML=issueTable(rows)}
function setMapLayer(layer){state.mapLayers=layer;render()}
function focusSearch(){state.searchOpen=true;state.searchResults=[];render()}
function closeSearch(){state.searchOpen=false;state.searchResults=[];render()}
async function searchOperations(term){if(!term.trim()){state.searchResults=[];render();return}try{state.searchResults=await api('/api/search?q='+encodeURIComponent(term));render()}catch(e){toast(e.message)}}
function openSearchResult(kind,id){closeSearch();if(kind==='issue')viewIssue(id);else if(kind==='bus')viewBus(id);else location.hash='#/dashboard/incidents'}
function showNotifications(){toast(state.incidents.length?`${state.incidents.length} incident records loaded from the backend.`:'No critical notifications.')}
function connectRealtime(){try{const ws=new WebSocket(WS);ws.onmessage=e=>{const m=JSON.parse(e.data);if(m.type==='SIMULATION_STATUS'){state.live=m.data.status==='RUNNING';state.speed=m.data.speed;render()}if(m.type==='BUS_LOCATION_UPDATED'){const b=state.buses.find(x=>x.id===m.data.busId);if(b){b.lat=m.data.latitude;b.lon=m.data.longitude;b.location=`${Number(b.lat).toFixed(4)}° N, ${Number(b.lon).toFixed(4)}° E`}const marker=liveBusMarkers.get(m.data.busId);if(marker)marker.setLatLng([m.data.latitude,m.data.longitude]);return}if(['NEW_ROAD_ISSUE','ROAD_ISSUE_UPDATED','NEW_INCIDENT','TRAFFIC_UPDATED','MAINTENANCE_UPDATED'].includes(m.type)){hydrate()}};ws.onclose=()=>setTimeout(connectRealtime,2500)}catch(e){}}
window.simulationAction=simulationAction;window.setSpeed=setSpeed;window.createWorkOrder=createWorkOrder;window.advanceMaintenance=advanceMaintenance;window.generateReport=generateReport;window.openReport=openReport;window.viewIssue=viewIssue;window.viewBus=viewBus;window.viewEvidence=viewEvidence;window.exportJson=exportJson;window.filterIssues=filterIssues;window.setMapLayer=setMapLayer;window.focusSearch=focusSearch;window.closeSearch=closeSearch;window.searchOperations=searchOperations;window.openSearchResult=openSearchResult;window.showNotifications=showNotifications;window.hydrate=hydrate;
window.addEventListener('hashchange',route);route();hydrate();connectRealtime();
